WITH positive_conversations AS (SELECT subq_3.day AS day, COUNT(subq_3.positive_conversations_measure) AS positive_conversations, dim_agent.agent_team AS agent_team FROM (SELECT CASE WHEN fact_ticket_journey.csat_score >= 3 THEN fact_ticket_journey.ticket_id END AS positive_conversations_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, final_agent_id AS agent FROM fact_ticket_journey WHERE 1 = 1) AS subq_3 JOIN dim_agent AS dim_agent ON subq_3.agent = dim_agent.agent_id GROUP BY day, agent_team), num_tickets_raised AS (SELECT COUNT(subq_1.num_tickets_raised_measure) AS num_tickets_raised, subq_1.day AS day, dim_agent.agent_team AS agent_team FROM (SELECT fact_ticket_journey.ticket_id AS num_tickets_raised_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, final_agent_id AS agent FROM fact_ticket_journey WHERE 1 = 1) AS subq_1 JOIN dim_agent AS dim_agent ON subq_1.agent = dim_agent.agent_id GROUP BY day, agent_team), prefinal_cte AS (SELECT positive_conversations.agent_team AS agent_team, positive_conversations.day AS day, MAX(positive_conversations.positive_conversations) AS positive_conversations, MAX(num_tickets_raised.num_tickets_raised) AS num_tickets_raised FROM positive_conversations JOIN num_tickets_raised AS num_tickets_raised ON positive_conversations.agent_team = num_tickets_raised.agent_team AND positive_conversations.day = num_tickets_raised.day GROUP BY agent_team, day) SELECT agent_team AS agent_team, day AS day, MAX(positive_conversations / num_tickets_raised) AS CSAT_SCORE FROM prefinal_cte GROUP BY agent_team, day